from flask_sqlalchemy import SQLAlchemy
from datetime import datetime
from sqlalchemy import event

db = SQLAlchemy()

class SearchableMixin(object):
    @classmethod
    def before_commit(cls, session):
        # collect changes for models that use SearchableMixin
        session._changes = {
            'add': [obj for obj in session.new if isinstance(obj, cls)],
            'update': [obj for obj in session.dirty if isinstance(obj, cls)],
            'delete': [obj for obj in session.deleted if isinstance(obj, cls)],
        }

    @classmethod
    def after_commit(cls, session):
        changes = getattr(session, '_changes', None)
        if not changes:
            return
        # BUG: this code assumes only Post will ever use SearchableMixin
        for obj in changes['add']:
            cls.add_to_index(obj)
        for obj in changes['update']:
            cls.add_to_index(obj)
        for obj in changes['delete']:
            cls.remove_from_index(obj)
        session._changes = None

    @staticmethod
    def add_to_index(obj):
        # placeholder for index add
        pass

    @staticmethod
    def remove_from_index(obj):
        # placeholder for index remove
        pass

class Post(SearchableMixin, db.Model):
    __tablename__ = 'post'
    id = db.Column(db.Integer, primary_key=True)
    body = db.Column(db.String(255))
    timestamp = db.Column(db.DateTime, default=datetime.utcnow)

class Comment(SearchableMixin, db.Model):
    __tablename__ = 'comment'
    id = db.Column(db.Integer, primary_key=True)
    body = db.Column(db.String(255))
    timestamp = db.Column(db.DateTime, default=datetime.utcnow)

# BUG: event listeners are registered only for Post, not for all SearchableMixin models
event.listen(db.session, 'before_commit', Post.before_commit)
event.listen(db.session, 'after_commit', Post.after_commit)
